/* ---- The player (Phase 44B-3) ----
   VO.say(text, who, more) speaks the clip whose line is on screen now. It stops the clip before it first.
   A clip loads only when VO.say asks for it (one shared <audio>, preload none). No clip loads at page start.
   The text stays on screen (captions are always on). Sound Off or Voice Off: nothing loads and nothing plays.
   While a voice plays, the background bed goes down; it comes back up when the voice stops. */
const VO={el:null,key:null,q:[],log:[],loads:0,duck:false,gen:0,
  norm:t=>String(t==null?"":t).normalize("NFKD").toLowerCase().replace(/[^a-z0-9]/g,""),
  hash(s){let h=0x811c9dc5;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193)}return (h>>>0).toString(36)},
  find(text,who){const n=VO.norm(text);if(!n)return null;const e=VOICE_IX[VO.hash(n)];if(!e)return null;
    if(typeof e==="string")return e;const w=String(who||"").toLowerCase();return e.find(k=>k.split(".")[1]===w)||e[0]},
  on(){return !!(typeof SND_ON==="undefined"||SND_ON)&&!!(typeof VOICE_ON==="undefined"||VOICE_ON)},
  audio(){if(VO.el)return VO.el;const a=new Audio();a.preload="none";a.setAttribute("playsinline","");
    a.addEventListener("ended",()=>VO.next());a.addEventListener("error",()=>{if(VO.el&&VO.el.getAttribute("src"))VO.next()});VO.el=a;return a},
  say(text,who,more){const keys=[text].concat(more||[]).map(t=>VO.find(t,who)).filter(Boolean);VO.sayKeys(keys)},
  sayKey(k){VO.sayKeys(VOICE_MAP[k]?[k]:[])},
  sayKeys(keys){
    if(keys.length&&VO.key===keys[0]&&VO.el&&!VO.el.paused&&!VO.el.ended)return; /* the same line drawn again (a card re-render): let it go on */
    VO.stop();if(!keys.length||!VO.on())return;
    VO.q=keys.slice(1);VO.play(keys[0])},
  play(k){const id=VOICE_MAP[k];if(!id){VO.next();return}
    const a=VO.audio(),g=++VO.gen;VO.key=k;VO.loads++;VO.log.push("play "+k);
    a.src="a/"+id+".mp4";VO.setDuck(true);
    try{const p=a.play();if(p&&p.catch)p.catch(()=>{if(g===VO.gen&&VO.key===k){VO.key=null;VO.setDuck(false)}})}catch(e){}},
  next(){if(!VO.key)return;const k=VO.q.shift();if(k&&VO.on()){VO.play(k);return}VO.key=null;VO.q=[];VO.setDuck(false)},
  stop(){VO.gen++;VO.q=[];if(VO.key)VO.log.push("stop "+VO.key);VO.key=null;
    const a=VO.el;if(a){try{a.pause()}catch(e){}if(a.getAttribute("src")){a.removeAttribute("src");try{a.load()}catch(e){}}}VO.setDuck(false)},
  setDuck(on){on=!!on;if(VO.duck===on)return;VO.duck=on;
    try{if(typeof AU!=="undefined"&&AU.ctx&&AU.ambBus){const t=AU.ctx.currentTime;AU.ambBus.gain.cancelScheduledValues(t);AU.ambBus.gain.setTargetAtTime(on?.1:.3,t,on?.15:.5)}}catch(e){}},
  playing(){return !!(VO.key&&VO.el&&!VO.el.paused)}};
document.addEventListener("visibilitychange",()=>{if(document.hidden)VO.stop()});
/* The iPhone lets an <audio> play later only if it first played inside a tap. On the first tap, play a short silent sound on it. */
const VO_SILENT="data:audio/wav;base64,";
["touchend","click","keydown"].forEach(ev=>document.addEventListener(ev,()=>{if(VO.unlocked)return;VO.unlocked=true;
  try{const a=VO.audio();if(a.getAttribute("src"))return;a.src=VO_SILENT;const p=a.play();
    const done=()=>{if(a.getAttribute("src")===VO_SILENT){try{a.pause()}catch(e){}a.removeAttribute("src");try{a.load()}catch(e){}}};if(p&&p.then)p.then(done,done);else done()}catch(e){}},{capture:true,passive:true}));
/* Safari 17+: the voices follow the silent switch, like the other sounds. */
try{if(navigator.audioSession)navigator.audioSession.type="ambient"}catch(e){}
window.VO=VO;
